    for (int i = 0; i < len; i++) { 
        char c = str.charAt(i); 
        if (c != '\\') { 
            sb.append(c); 
            continue; 
        } 
        if (i + 1 >= len) { 
            sb.append('\\'); 
            break; 
        } 
        char next = str.charAt(i + 1); 
        switch (next) { 
            case '\\': 
                sb.append('\\'); 
                i++; 
                break; 
            case 'n': 
                sb.append('\n'); 
                i++; 
                break; 
            case 't': 
                sb.append('\t'); 
